 setTheme(savedTheme(),{persist:false});renderScreen();if(!state.playing){$('#mode-state').textContent='PAUSED';setStatus(' Reduced motion: обновление остановлено · → один sample');}
 window.SacraTUI={state,jobs,go,setRenderer,tick,renderPlots,windowHistory,exportFrame,setTheme,showThemes,toggleGrid,colors};
